/// The content class claiming `option` of scenery `id`, if any.
pub fn claim(id: i32, option: &str) -> Option<&'static str> {
    let at = CLAIMS.partition_point(|(i, o, _)| (*i, *o) < (id, option));
    CLAIMS
        .get(at)
        .filter(|(i, o, _)| *i == id && *o == option)
        .map(|(_, _, c)| *c)
}

/// The content class claiming `option` of the object at `at`, if any.
pub fn claim_at(at: [i32; 3], option: &str) -> Option<&'static str> {
    LOCATIONS
        .iter()
        .find(|(l, o, _)| *l == at && *o == option)
        .map(|(_, _, c)| *c)
}
